python
def stampGatesFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    for x in a: out.append(max(0,x))
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int stampGatesFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)out.add(Math.max(0,x));}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
